--
-- Table structure for table `payments`
--

DROP TABLE IF EXISTS `payments`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `payments` (
  `id` char(36) NOT NULL,
  `booking_id` char(36) NOT NULL,
  `amount` decimal(10,2) NOT NULL,
  `method` varchar(5) NOT NULL,
  `status` varchar(7) NOT NULL,
  `transaction_time` timestamp NOT NULL,
  `provider_transaction_id` varchar(100) DEFAULT NULL,
  `payment_info` text COMMENT 'Thông tin bổ sung về giao dịch (JSON)',
  `description` varchar(255) DEFAULT NULL,
  `raw_response` text COMMENT 'Dữ liệu phản hồi từ hệ thống thanh toán',
  `secure_hash` varchar(255) DEFAULT NULL COMMENT 'Mã bảo mật HMAC để xác minh giao dịch',
  `created_at` timestamp NOT NULL,
  `updated_at` timestamp NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `booking_id` (`booking_id`),
  UNIQUE KEY `provider_transaction_id` (`provider_transaction_id`),
  KEY `ix_payments_id` (`id`),
  KEY `ix_payments_status` (`status`),
  KEY `ix_payments_created_at` (`created_at`),
  KEY `ix_payments_method` (`method`),
  KEY `ix_payments_booking_id` (`booking_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

